cat > .local/smart-shorts-seven/verify-delivery.mjs <<'EOF'
import {readFileSync,writeFileSync} from 'node:fs';
import assert from 'node:assert/strict';
const before=JSON.parse(readFileSync(new URL('./project-before.json',import.meta.url)));
const after=JSON.parse(readFileSync('/Users/itayzrihan/Movies/OpenCut Accounts/data/4fec0688-9a78-4304-849c-9ea937873751/projects/11e7e552-fd67-44e7-8795-cd2b8b5e2668/project.json'));
const original=before.scenes.find(s=>s.isMain), main=after.scenes.find(s=>s.id===original.id);
assert(main?.isMain,'Original main scene missing');
assert.deepEqual(main.tracks.main,original.tracks.main,'Main source video changed');
assert.deepEqual(main.tracks.audio,original.tracks.audio,'Main audio changed');
for(const track of original.tracks.overlay){
 const updated=main.tracks.overlay.find(t=>t.id===track.id);assert(updated,'Original caption track missing');
 const elements=new Map(updated.elements.map(e=>[e.id,e]));
 for(const element of track.elements)assert.deepEqual(elements.get(element.id),element,'Original caption changed or deleted');
 if(track.captionSource)assert.deepEqual(updated.captionSource.words.slice(0,track.captionSource.words.length),track.captionSource.words,'Original transcript words changed');
}
const oldJob=before.transcriptionJobs[0], job=after.transcriptionJobs.find(j=>j.id===oldJob.id);
assert.equal(job.status,'complete');assert.equal(Object.keys(job.chunks).length,108);
for(const [index,words]of Object.entries(oldJob.chunks))assert.deepEqual(job.chunks[index],words,'Saved transcription section changed');
const outputs=after.scenes.filter(s=>!before.scenes.some(o=>o.id===s.id));assert.equal(outputs.length,7);
const clips=outputs.map(s=>{assert(!s.isMain);assert(s.podcastExtract);assert(s.takeAssembly);assert(s.tracks.main.elements.length>0);return{id:s.id,name:s.name,title:s.podcastExtract.title,seconds:Math.max(...s.tracks.main.elements.map(e=>(e.startTime+e.duration)/120000))};});
const summary={verifiedAt:new Date().t

